"""Publish findings and review coverage, keeping raw ASR out of the delivery ZIP."""
from pathlib import Path
import json,hashlib
from revision3_data import OUT,HERE,ORIGINS,BUILDS
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def stamp(t):return f'{t//3600:02}:{t//60%60:02}:{t%60:02}'
def url(v,t):return f'https://www.twitch.tv/videos/{v}?t={t//3600}h{t//60%60}m{t%60}s'
A=HERE/'broadcast_audit'
VODS=[('2865212551',16953,'2026-09-04'),('2866065347',20678,'2026-09-05'),('2866749730',31343,'2026-09-06')]
EVIDENCE=[
 ('2865212551',6798,'초반 목전 I','몰려오는 강타를 선택하고 목전 I를 제작하는 화면. 초반 기절 I 추천을 제거.',6798),
 ('2865212551',7252,'충격파 토템 시작','3레벨 스킬 젬의 요구 조건은 캐릭터 6레벨·힘 14. 캐릭터 3레벨과 구분.',7252),
 ('2865212551',7628,'초기 토템 보조','충격파 토템에 과잉 I를 선택. 이후 지속시간 불편을 말하고 공격 속도 연결로 바뀜.',7628),
 ('2865212551',8010,'근접 피해 시작','캐릭터 8레벨에서 근접 피해 10% 시작 경로 확인. 기절 축적 시작으로 안내한 이전 오류 수정.',8010),
 ('2865212551',13942,'한손 철퇴','Spiked Club 한손 철퇴의 무기 수치 확인. 초반 양손 철퇴를 필수로 안내할 근거 없음.',13942),
 ('2865212551',16689,'첫 전직','응답받은 부름 선택 화면과 24레벨 공개 스냅샷의 실제 배정을 함께 확인.',16689),
 ('2865212551',16810,'첫날 무기 세트','I 한손 철퇴+방패, II의 철퇴/공유 방패 구성을 확인.',16810),
 ('2866065347',2940,'망치와 함성 해금','미가공 스킬 젬 9레벨 제작 목록에 대장간 망치와 보강하는 함성이 표시됨.',2940),
 ('2866065347',10560,'두 번째 전직','혼돈의 시련 진행 화면과 43레벨 공개 스냅샷에서 전쟁 소집자의 고함 확인. 공개 노드 ID로 확정.',None),
 ('2866065347',16050,'타락 함성 전환','4시간 23~33분 사이 환불·젬 설정. 46레벨 스냅샷으로 새 트리와 함성 연결을 대조.',16050),
 ('2866065347',16420,'타락 함성 실제 사용','보강하는 함성 사용과 희귀 적의 타락한 피 7중첩 표시. 마나와 생명력이 남아 있는 상태.',16420),
 ('2866065347',18005,'전사 토템 요구 레벨','젬 13레벨 선대의 전사 토템이 캐릭터 52레벨을 요구하는 화면. 이 순간 캐릭터 자체는 48레벨.',18005),
 ('2866749730',1620,'전사 토템 환불 시작','00:27~00:38 구간에서 트리·셉터·혈마법·토템을 연속 변경. 97포인트 후기 트리 완성을 기다리지 않음.',1620),
 ('2866749730',1770,'혈마법 도입','전환 중 마나가 0/0이 된 화면. 선대의 유대/혈마법 사용은 영상과 후기 실측으로 교차 확인.',1770),
 ('2866749730',1950,'정신력 셉터','정신력 149 Honour Grinder 성소 셉터와 I의 방패 유지 확인. 후기 보존본에서도 동일 고유 ID의 희귀 셉터 확인.',1950),
 ('2866749730',1980,'54레벨 트리 범위','0 미사용 일반 포인트, 무기 특화 각 4/18 미사용. 화면 밖 노드와 모든 배정은 복원 불충분하므로 69점 제공안은 재구성안으로 표시.',1980),
 ('2866749730',2040,'전사 토템 초기 보조','파생하는 균열 I 제작 화면. 초기 AWT에 긴급한 토템 I를 넣었다는 기존 추정 제거.',2040),
 ('2866749730',2100,'실제 전환 상태','캐릭터 54레벨, 생명력 1442·재생 56.5/초·번개 저항 35%. 이 수치를 하코 권장 장비 기준으로 복사하지 않음.',2100),
 ('2866749730',2310,'젬 설명과 실제 비용','AWT 유효 15레벨/기본 13레벨, 품질 20, 요구 캐릭터 52레벨. 혈마법 상태에서도 젬 설명의 기본 비용은 Mana로 표시되므로 그대로 실사용 비용이라 부르지 않음.',2310),
 ('2866749730',2938,'무기 세트 수정','집중 전사 00:48:58과 00:49:00 G 화면에서 AWT의 I 체크 해제·II 체크 확인. 큰 전사 블록의 시작 시각 00:46:32와 구분.',2940),
 ('2866749730',2940,'토템 정신력과 지속시간','G 화면에 토템당 정신력 75·실제 지속시간 13초 표시. 4기 정신력 조건을 양 무기 세트에 적용.',2940),
 ('2866749730',11070,'양손 철퇴 거부 이유','약 03:04:30에 하코에서 거인의 피의 힘 생명력 불이익을 원치 않는다고 설명. 현재 경로의 양손 철퇴 전환 의무 제거.',None),
 ('2866749730',12960,'셉터 버프와 AWT','I 불의 순수함에 활력 II·식인 II, II에 활력 I, AWT의 지면 분쇄와 두 보조를 화면으로 대조. 54레벨 직후의 모든 보조 소켓 변경 순서와 동일하다고 주장하지 않음.',12960),
 ('2866749730',14212,'65레벨 파콰테 도입','집중 전사 03:56:52부터 설정. 04:04:21 두 함성 운영을 설명. 파콰테만 바꾸는 전환이 아님.',None),
 ('2866749730',14580,'두 함성 연결 준비','지진 함성의 보조 젬 제작 메뉴와 후속 실제 연결을 대조. 06에서 우주의 영사·효율 II·격노하는 함성을 별도로 안내.',14580),
 ('2866749730',16230,'파콰테 실제 툴팁','요구 레벨 65, 최근 사용·발동 횟수에 따른 최대 생명력 추가 비용과 30% 상한 표시. 반복의 모든 비용 의미는 화면 한 장으로 확정하지 않음.',16230),
 ('2866749730',17973,'메아리 회복 발언','집중 전사에서 04:59:33에 메아리마다 회복된다는 발언 확인. 회복량·비용까지 정량 검증한 증거는 아니므로 시뮬레이션에서 가정을 나눔.',17973),
 ('2866749730',22590,'후기 선택 고유','Sadist’s Mercy 한손 철퇴 툴팁: 요구 레벨 67. 전사 토템의 초기 전환 필수 아이템으로 두지 않음.',22590),
 ('2866749730',25380,'세 번째 전직','전직 화면·발언과 74레벨 공개 패시브에서 나무 벽 확인. 65레벨 파콰테 도입과 별개의 후속 진행.',25380),
 ('2866749730',26130,'토템 4기와 효과 누적','토템 4기 화면과 함성 효과/성능 저하 재현. 임시 5기 초과 현상은 정상 유지 가능한 토템 수에 포함하지 않음.',26130),
 ('2866749730',26310,'후기 함성 사용','후반 사냥 화면·운영 설명·74레벨 젬 연결을 대조. 토템 가시는 지진 함성, 파콰테는 보강하는 함성에 유지.',26310),
 ('2866749730',31140,'공개 방송 종료 상태','마지막까지 74레벨 하코 캐릭터로 진행한 전사/화면을 확인. 이후의 영구 생존 보장이나 현재 접속 여부로 확대하지 않음.',None)
]

def main():
    rows=[]
    for v,t,topic,finding,frame in EVIDENCE:
        entry={'video':v,'at':t,'topic':topic,'finding':finding,'url':url(v,t),'evidence_type':'원본 고화질 화면 + 전사 문맥' if frame is not None else '전사 문맥 + 해당 공개 스냅샷/탐색 화면'}
        if frame is not None:
            p=A/v/'frames'/f'hd_{frame:06}.jpg';assert p.exists(),p
            entry['frame']=str(p);entry['sha256']=hashlib.sha256(p.read_bytes()).hexdigest()
        rows.append(entry)
    coverage=[];notes=read(A/'review_notes.json')
    for v,d,date in VODS:
        first=read(A/v/'asr_coverage.json');second=read(A/v/'asr_coverage_large_v3.json')
        for cov in (first,second):
            end=0
            for a,b in cov['processed_intervals']:assert a<=end+.01;end=max(end,b)
            assert end>=d-1
        assert len(notes['reviewed_transcript_chunks'][v])==len(first['processed_intervals'])
        assert len(notes['reviewed_second_asr_chunks'][v])==len(second['processed_intervals'])
        count=len(read(A/v/'frames/index_scan.json'))
        coverage.append({'id':v,'duration':d,'date':date,'two_full_asr_passes':True,'reviewed_first_chunks':len(first['processed_intervals']),'reviewed_second_chunks':len(second['processed_intervals']),'scan_frames':count})
    (A/'key_scene_evidence.json').write_text(json.dumps({'coverage':coverage,'events':rows,'review_method':notes['visual_method'],'audio_limit':notes['asr_method_limit']},ensure_ascii=False,indent=2),encoding='utf-8')
    for e in notes['events']:
        e['verification']='전체 두 전사 문맥 대조 완료. 이 후보의 자동 전사 시작 시각은 근사값일 수 있음. 설정 채택 여부와 정확한 핵심 시각은 key_scene_evidence.json 및 최종 보고서를 기준으로 함.'
    notes['completion']=True;notes['completion_scope']='전체 2회 ASR 문맥 대조, 30초 탐색 화면 전체 검토, 빌드 변경에 채택한 핵심 원본 화면/공개 스냅샷 대조. 모든 원본 음성 직접 청취나 모든 영상 프레임 검토를 뜻하지 않음.'
    (A/'review_notes.json').write_text(json.dumps(notes,ensure_ascii=False,indent=2),encoding='utf-8')
    doc=['# Skadoosh 방송 대조 보고서 · v3','','이전의 “라이브를 전부 확인했다”는 설명은 당시 수행한 검토 범위를 넘었다. 이번에는 아래 세 방송 전체를 두 번 전사해 읽고, 화면과 실제 공개 캐릭터를 추가 대조했다.','',
      '## 범위와 방법','','| 방송 | 날짜 | 길이 | 전사 대조 | 30초 탐색 화면 |','|---|---|---|---|---|']
    for i,c in enumerate(coverage,1):doc+=[f"| [첫날부터 {i}번째 방송](https://www.twitch.tv/videos/{c['id']}) | {c['date']} | {stamp(c['duration'])} | {c['reviewed_first_chunks']} + {c['reviewed_second_chunks']} 구간 | {c['scan_frames']}장 |"]
    doc+=['','합계 18시간 52분 54초. 제공 자막/자동 자막 트랙이 없어 원본 전체 음성으로 ASR을 생성했다. large-v3-turbo와 large-v3를 각각 사용하고, 20분 구간에 5초 겹침을 뒀다. 두 결과를 끝까지 읽어 문맥을 비교했다. 핵심 구간은 VAD 없는 추가 전사로 발언 시각을 좁혔다. 2,301장의 30초 간격 화면을 93개 보드로 검토하고 중요한 설정은 1080p 원본 프레임으로 다시 확인했다.','',
      '두 전사는 같은 원본을 사용하므로 독립적인 출처 두 개가 아니다. 사람이 원음을 18시간 전부 청취하거나 영상을 매초 재생한 검토라고 부르지 않는다. 자동 전사에는 게임 대사·조용한 발언 누락·환각이 남을 수 있어 스킬/장비 결론은 화면과 공개 데이터로 보강했다. 원본 전체 전사·영상은 내부 검토 자료로 보관하고 배포 ZIP에는 넣지 않았다.','',
      '## 기존 안내에서 고친 점','','- 근접 피해 시작, 초반 목전 I, 충격파 토템의 캐릭터 6레벨 조건을 확인했다.\n- 초반부터 양손 철퇴를 필수로 쓰도록 했던 안내를 한손 철퇴+방패 경로로 고쳤다.\n- 전사 토템 전환에 후기 97점 트리 완성을 요구하지 않는다. 실제 제작자는 54레벨에 전환했다.\n- 54레벨의 모든 화면 밖 노드를 복원하지 못했으므로 05는 69점 재구성안으로 표시하고 별도 계산했다.\n- 파콰테는 65레벨 이후 두 함성 운영으로 설명한다. 지진 함성의 보조와 역할을 추가했다.\n- 사소한 링크/키스톤 시험을 별도 파일로 쪼갠 13개 구성을 7개로 정리했다.\n- 하코 65레벨 이상에서 남는 포인트는 회복·방어를 먼저 확장하는 80점 경로로 안내한다.','',
      '## 원본 시각과 판정','','| 방송 / 시각 | 확인한 내용 | 반영 |','|---|---|---|']
    for e in rows:doc+=[f"| [{e['video']} / {stamp(e['at'])}]({e['url']}) | {e['topic']} | {e['finding']} |"]
    doc+=['','## 혼동해서 제외한 내용','','첫날의 발로그 곰·젬링 Corrupting Wings 질의응답, 둘째 날 고레벨 젬링의 큰 방어 수치, 셋째 날 스탠다드 빌드/발로그 무기 질문은 현재 하코 워브링어의 설정으로 복사하지 않았다. 셋째 날 05:05~05:31:30은 식사 중 다른 방송 시청, 이어지는 약 05:41까지는 다른 클립, 05:42~05:56:30은 검은 식사 화면이다. 그 구간의 다른 캐릭터 장비·사망을 제작자 진행으로 취급하지 않았다.','',
      '지진 지대와 AWT/보강하는 함성의 시각 효과 누적 문제는 이 방송 당시 확인된 문제다. 현재 패치에서 수정 완료됐다는 공식 확인은 확보하지 못했다. 임시로 정상 한도를 넘긴 토템은 유지력 계산에 포함하지 않았다.','',
      '## 파일 형식의 한계','','[GGG 공식 Build Planner 문서](https://www.pathofexile.com/developer/docs/game#buildplanner)는 메타 젬을 현재 지원하지 않는다고 명시한다. 전사 토템 안의 지면 분쇄는 별도 획득 항목과 양쪽 설명으로 안내한다. 일반 보조는 토템의 support_skills에 넣었다. G의 무기 세트 체크박스와 장비 옵션 자동 선택은 저장 필드가 없어 직접 설정해야 한다. 플래너가 모든 게임 설정을 자동 적용한다고 주장하지 않는다.','',
      '## 남는 검증 한계','','파콰테/메아리의 실제 반복 비용과 회복량은 정량 확정하지 못했다. 비용 해석에 따라 자원 계산의 성공/실패가 갈려 06은 낮은 지역에서 비용을 확인한 뒤 쓰는 조건부 단계다. 05의 69점 안은 실제 54레벨 전체 트리 복제본이 아니다. 새 파일의 게임 내 재로딩·실전 조작과 가속 희귀 다수 의식 생존은 직접 시험하지 않았다. “완벽하게 안전하다”는 결론은 내리지 않는다.','',
      '기준 공개 캐릭터: [SkadooshShoutedHard](https://poe.ninja/poe2/builds/forbiddenriteshc/character/ITheCon-2183/SkadooshShoutedHard). 24·43·46·52·74레벨 보존본으로 시점을 분리했다. 추가 최신 조회는 75레벨/updatedUtc 2026-09-07T02:31:45Z였으며, 74레벨 플래너에 최신 젬만 섞지 않았다.','']
    (OUT/'방송대조보고서.md').write_text('\n'.join(doc),encoding='utf-8')
    print('Audit: all three full ASR comparisons, 2301 scan frames, '+str(len(rows))+' cited key findings.')
if __name__=='__main__':main()
